        catch (ArgumentOutOfRangeException)
        {
            Console.WriteLine($"{label} -> DITOLAK: jumlah tidak sah");
        }
        catch (InvalidOperationException e)
        {
            Console.WriteLine($"{label} -> DITOLAK: {e.Message}");
        }
    }

